import os, sys, time
import torch
sys.path.insert(0, "/tmp")
import fp4_infra as f
_fp4_bmm = f._fp4_bmm
_quant_lhs_b = f._quant_lhs_b
_quant_rhs_b = f._quant_rhs_b
_bmm_fp4 = f._bmm_fp4

dev = "cuda"
torch.manual_seed(0)
torch.backends.cuda.matmul.allow_tf32 = True

def bench(fn, iters=50, warmup=10):
    for _ in range(warmup): fn()
    torch.cuda.synchronize()
    t0 = time.perf_counter()
    for _ in range(iters): fn()
    torch.cuda.synchronize()
    return (time.perf_counter()-t0)/iters*1e6

N = 512; B = 640
print(f"=== n={N} B={B}: W = V^T @ A_trail   (K=pheight contraction) ===")
print(f"{'NB':>5} {'ncols':>6} {'tf32bmm':>9} {'fp4(q+dot)':>11} {'fp4/tf32':>9} {'dot_only':>9} {'quant':>9}")
for NB in (32, 64, 128, 256):
    pheight = N
    ncols = N - NB
    V = torch.randn(B, NB, pheight, device=dev)
    A = torch.randn(B, pheight, ncols, device=dev)
    def tf32():
        return torch.bmm(V, A)
    t_tf32 = bench(tf32)
    def fp4full():
        return _bmm_fp4(_quant_lhs_b(V), _quant_rhs_b(A), NB, ncols)
    t_fp4 = bench(fp4full)
    Vq = _quant_lhs_b(V); Aq = _quant_rhs_b(A)
    def fp4dot():
        return _bmm_fp4(Vq, Aq, NB, ncols)
    t_dot = bench(fp4dot)
    def qonly():
        return _quant_rhs_b(A)
    t_q = bench(qonly)
    print(f"{NB:>5} {ncols:>6} {t_tf32:>9.1f} {t_fp4:>11.1f} {t_fp4/t_tf32:>9.2f} {t_dot:>9.1f} {t_q:>9.1f}")

print()
print(f"=== n={N} B={B}: delta = V @ YT   (K=NB contraction) ===")
print(f"{'NB':>5} {'ncols':>6} {'tf32bmm':>9} {'fp4(q+dot)':>11} {'fp4/tf32':>9} {'dot_only':>9}")
for NB in (32, 64, 128, 256):
    pheight = N
    ncols = N - NB
    Vd = torch.randn(B, pheight, NB, device=dev)
    YT = torch.randn(B, NB, ncols, device=dev)
    def tf32d():
        return torch.bmm(Vd, YT)
    t_tf32 = bench(tf32d)
    def fp4fulld():
        return _bmm_fp4(_quant_lhs_b(Vd), _quant_rhs_b(YT), pheight, ncols)
    t_fp4 = bench(fp4fulld)
    Vdq = _quant_lhs_b(Vd); YTq = _quant_rhs_b(YT)
    def fp4dotd():
        return _bmm_fp4(Vdq, YTq, pheight, ncols)
    t_dot = bench(fp4dotd)
    print(f"{NB:>5} {ncols:>6} {t_tf32:>9.1f} {t_fp4:>11.1f} {t_fp4/t_tf32:>9.2f} {t_dot:>9.1f}")

# also test torch._scaled_mm path (cuBLAS-tiled FP8) as upper-bound reference
print()
print("=== reference: torch._scaled_mm FP8 (cuBLAS) for a COMPUTE-BOUND square GEMM ===")
for sz in (512, 1024, 2048):
    a = torch.randn(sz, sz, device=dev, dtype=torch.bfloat16)
    b = torch.randn(sz, sz, device=dev, dtype=torch.bfloat16)
    def tf():
        return torch.matmul(a, b)
    t_tf = bench(tf)
    try:
        af = a.to(torch.float8_e4m3fn); bf = b.t().contiguous().to(torch.float8_e4m3fn).t()
        sa = torch.ones((), device=dev); sb = torch.ones((), device=dev)
        def fp8():
            return torch._scaled_mm(af, bf, scale_a=sa, scale_b=sb, out_dtype=torch.bfloat16)
        t_fp8 = bench(fp8)
        print(f"  sz={sz}: bf16 {t_tf:.1f}us  fp8 {t_fp8:.1f}us  ratio {t_fp8/t_tf:.2f}")
    except Exception as e:
        print(f"  sz={sz}: fp8 failed: {e}")

